def count_subsequence_matches(text: str, sub: str) -> int:
    m, n = len(text), len(sub)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # If the substring is empty, there is only one way to form it (by not choosing any characters)
    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if text[i - 1] == sub[j - 1]:
                # If the current characters match, we can either choose to include it in the subsequence or not
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                # If the current characters don't match, we can only choose not to include it in the subsequence
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]
```

