def count_interval_overlaps(intervals: list[tuple[int, int]]) -> int:
    # Sort the intervals by their start times
    intervals.sort(key=lambda x: x[0])

    count = 0
    for i in range(len(intervals) - 1):
        # If the current interval ends after the next one starts, they overlap
        if intervals[i][1] >= intervals[i + 1][0]:
            count += 1
    return count

