def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'
    res = []
    while n != 0:
        if n % 3 == 0:
            res.append('0')
        elif n % 3 == 1:
            res.append('+')
            n -= 1
        elif n % 3 == 2:
            res.append('-')
            n += 1
        n //= 3
    return ''.join(res[::-1])
