def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi:
        return 0

    # Find the highest power of 2 less than or equal to hi
    max_power = 0
    while (1 << (max_power + 1)) <= hi:
        max_power += 1

    # Initialize the dp table
    dp = [[0] * (max_power + 1) for _ in range(2)]
    dp[0][0] = dp[1][0] = 1
    for i in range(1, max_power):
        dp[0][i] = dp[0][i - 1] * 2
        dp[1][i] = dp[1][i - 1] * 2 + (1 << i)

    # Calculate the number of set bits in the range [lo, hi]
    def count_set_bits(n: int) -> int:
        if n <= 1:
            return n

        max_power = 31 - n.bit_length()
        return dp[1][max_power] + n - (1 << (max_power + 1)) + 1 + count_set_bits(n % (1 << max_power))

    return count_set_bits(hi) - count_set_bits(lo - 1)
