def make_tar(directory: str, archive_path: str) -> str:
    if not os.path.isdir(directory):
        raise ValueError(f"Directory {directory} does not exist")
    if os.path.exists(archive_path):
        raise ValueError(f"File {archive_path} already exists")

    # Use the tar command to create the archive
    subprocess.run(["tar", "-C", os.path.dirname(directory), "-cf", archive_path, os.path.basename(directory)], check=True)

    return archive_path

