from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start == (-1, -1) or end == (-1, -1):
        return -1

    moves = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[0]*cols for _ in range(rows)]
    visited[start[0]][start[1]] = 1
    queue = deque([(*start, 0)])  # (row, col, moves)

    while queue:
        curr_row, curr_col, curr_moves = queue.popleft()
        for move in moves:
            next_row, next_col = curr_row + move[0], curr_col + move[1]
            if 0 <= next_row < rows and 0 <= next_col < cols and visited[next_row][next_col] == 0:
                if grid[next_row][next_col] == '#':  # hit a wall
                    queue.append((next_row, next_col, curr_moves + 1))
                    visited[next_row][next_col] = 1
                elif grid[next_row][next_col] == '.':  # empty cell
                    if (next_row, next_col) == end:
                        return curr_moves + 1
                    queue.append((next_row, next_col, curr_moves))
                    visited[next_row][next_col] = 1
    return -1
