```python
from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    visited = [[[0, 0] for _ in range(cols)] for _ in range(rows)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    q = deque()

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                q.append((i, j, 0, 0))
                visited[i][j][0] = 1

    while q:
        x, y, w, d = q.popleft()
        if grid[x][y] == 'E':
            return d
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[nx][ny] == '#' and w == 0 and visited[nx][ny][1] == 0:
                    visited[nx][ny][1] = 1
                    q.append((nx, ny, 1, d + 1))
                elif grid[nx][ny] == '.' and visited[nx][ny][w] == 0:
                    visited[nx][ny][w] = 1
                    q.append((nx, ny, w, d + 1))
    return -1
