def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Initialize the board
    board = [['O' for _ in range(n)] for _ in range(n)]

    # Mark blocked squares
    for block in blocked:
        if 0 <= block[0] < n and 0 <= block[1] < n:
            board[block[0]][block[1]] = 'B'

    # Function to check if a queen can be placed safely
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 'Q':
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 'Q':
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 'Q':
                return False

        return True

    # Function to place queens
    def solve_n_queens(board, col):
        # Base case: If all queens are placed
        if col >= n:
            return 1

        # Consider this column and try placing a queen in all rows one by one
        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                # Place this queen in board[i][col]
                board[i][col] = 'Q'
                # Recur for remaining queens
                count += solve_n_queens(board, col + 1)
                # Remove queen from board[i][col]
                board[i][col] = 'O'

        return count

    return solve_n_queens(board, 0)
