def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    # Create a board of size n x n and fill it with 0s
    board = [[0]*n for _ in range(n)]

    # Mark blocked cells as -1
    for block in blocked:
        if 0 <= block[0] < n and 0 <= block[1] < n:
            board[block[0]][block[1]] = -1

    def is_attack(i, j):
        # Check if there is a queen in row or column
        for k in range(0, n):
            if board[i][k] == 1 or board[k][j] == 1:
                return True
        # Check diagonals
        for k in range(0, n):
            for l in range(0, n):
                if (k+l == i+j) or (k-l == i-j):
                    if board[k][l] == 1:
                        return True
        return False

    def n_queens(n):
        # If n is 0, solution found
        if n == 0:
            return 1
        count = 0
        for i in range(0, len(board)):
            for j in range(0, len(board[0])):
                # Check if cell is not blocked and no attack
                if board[i][j] == 0 and not is_attack(i, j):
                    board[i][j] = 1
                    # Recursive call
                    count += n_queens(n-1)
                    # Backtrack
                    board[i][j] = 0
        return count

    return n_queens(n)
