from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    graph = defaultdict(list)
    in_degree = [0]*n

    for a, b in pairs:
        if a == b:
            return []
        graph[a].append(b)
        in_degree[b] += 1

    zero_in_degree = deque()
    for i in range(n):
        if in_degree[i] == 0:
            zero_in_degree.append(i)

    topological_order = []
    while zero_in_degree:
        u = zero_in_degree.popleft()
        topological_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                zero_in_degree.append(v)

    if len(topological_order) == n:
        return topological_order
    else:
        return []
