from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (-1, -1), (-1, -1)
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)
    if start == (-1, -1) or end == (-1, -1):
        return -1

    queue = deque([(*start, 0, False)])  # (row, col, steps, broken)
    visited = {start: (0, False)}  # (steps, broken)
    while queue:
        row, col, steps, broken = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#' and not broken and (nr, nc) not in visited or \
                   (visited[nr, nc][1] and visited[nr, nc][0] > steps + 1):
                    visited[nr, nc] = (steps + 1, True)
                    queue.append((nr, nc, steps + 1, True))
                elif grid[nr][nc] == '.' or (grid[nr][nc] == '#' and broken):
                    if (nr, nc) not in visited or visited[nr, nc][0] > steps + 1:
                        visited[nr, nc] = (steps + 1, broken)
                        queue.append((nr, nc, steps + 1, broken))
    if end in visited:
        return visited[end][0]
    return -1
```

