def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Create adjacency list
    adj_list = defaultdict(list)
    for a, b in pairs:
        if a == b:
            return []
        adj_list[a].append(b)

    # Count in-degree of each vertex
    in_degree = [0] * n
    for a, b in pairs:
        in_degree[b] += 1

    # Enqueue all vertices with in-degree 0
    q = deque(i for i in range(n) if in_degree[i] == 0)

    # For lexicographically smallest order
    res = []

    while q:
        u = q.popleft()
        res.append(u)

        for v in adj_list[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # If all tasks are not visited, then there is a cycle
    if len(res) != n:
        return []

    return res

