def solve_congruences(congruences: List[Tuple[int, int]]) -> Tuple[int, int] | None:
    if not congruences:
        return 0, 1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    r, m = congruences[0]
    for r1, m1 in congruences[1:]:
        r, m = (r * m1 + r1 * m) % (m * m1), lcm(m, m1)

    g = gcd(r, m)
    r //= g
    m //= g

    if r:
        return None

    return m, m
