```python
from collections import defaultdict

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in pairs:
        if u == v:
            return []
        adj_list[u].append(v)

    # Initialize visited and rec_stack
    visited = [0]*n
    rec_stack = [0]*n

    # Store the lexicographically smallest topological order
    topo_order = []

    # Function to perform DFS
    def dfs(node):
        visited[node] = 1
        rec_stack[node] = 1

        for child in adj_list[node]:
            if visited[child] == 0:
                if dfs(child) == False:
                    return False
            elif rec_stack[child] == 1:
                return False

        rec_stack[node] = 0
        topo_order.append(node)
        return True

    # Perform DFS for all nodes
    for node in range(n):
        if visited[node] == 0:
            if dfs(node) == False:
                return []

    return topo_order[::-1]
