from collections import defaultdict, deque

def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n == 0:
        return []

    # Create adjacency list
    adj_list = defaultdict(list)
    for a, b in pairs:
        if a == b:
            return []
        adj_list[a].append(b)

    # Compute in-degree of each node
    in_degree = [0]*n
    for node in adj_list:
        for neighbor in adj_list[node]:
            in_degree[neighbor] += 1

    # Queue for nodes with in-degree 0
    queue = deque([i for i in range(n) if in_degree[i] == 0])

    # List for topological order
    topological_order = []

    while queue:
        # Pop a node from front of queue
        node = queue.popleft()
        topological_order.append(node)

        # Reduce in-degree of all neighboring nodes by 1
        for neighbor in adj_list[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If all nodes are not visited, there is a cycle
    if len(topological_order) != n:
        return []

    return topological_order

