def is_safe(board, row, col, n):
    # Check this row on left side
    for i in range(col):
        if board[row][i] == 1:
            return False

    # Check upper diagonal on left side
    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    # Check lower diagonal on left side
    for i, j in zip(range(row, n, 1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    return True

def solve_n_queens(board, col, n, blocked):
    if col == n:
        return True

    for i in range(n):
        if is_blocked(i, col, blocked) or not is_safe(board, i, col, n):
            continue

        board[i][col] = 1

        if solve_n_queens(board, col + 1, n, blocked):
            return True

        board[i][col] = 0

    return False

def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[0]*n for _ in range(n)]
    blocked_set = set(blocked)

    def is_blocked(row, col, blocked):
        return (row, col) in blocked

    if solve_n_queens(board, 0, n, blocked_set):
        return 1
    else:
        return 0
