```python
def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # Create a blocked set for faster lookup
    blocked_set = set(blocked)

    # Helper function to check if a queen can be placed at position (row, col)
    def can_place(row, col):
        for r, c in blocked_set:
            # If the blocked square is in the same row or column, or diagonal, return False
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True

    # Helper function to place queens recursively
    def place_queens(row):
        # If we've placed all queens, return 1
        if row == n:
            return 1

        count = 0
        # Try to place a queen in each column of the current row
        for col in range(n):
            # If we can place a queen at position (row, col), place it and move on to the next row
            if can_place(row, col):
                count += place_queens(row + 1)

        return count

    # Start by placing queens from the first row
