def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def dfs(nums, target, path, res, start):
        if target < 0:
            return  # backtracking
        if target == 0:
            res.append(path)
            return 
        for i in range(start, len(nums)):
            # i > start ensures that we don't use the same number twice in the same path
            # nums[i] is not used in the path, so we start from i+1
            dfs(nums, target-nums[i], path+[nums[i]], res, i+1)

    nums.sort()
    res = []
    dfs(nums, k, [], res, 0)
    return res

