from heapq import heappop, heappush

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = [(0, source, [source])]
    seen = set()
    paths = []

    while queue:
        (cost, node, path) = heappop(queue)
        if node not in seen:
            seen.add(node)
            if node == target:
                paths.append(path)
            for next_node in graph[node]:
                if next_node not in seen:
                    heappush(queue, (cost + 1, next_node, path + [next_node]))

    if not paths:
        return 0

    shortest_path_len = len(min(paths, key=len))
    return sum(1 for path in paths if len(path) == shortest_path_len)
