    def dfs(nums, k, start, path, res):
        if k < 0:
            return  # backtracking
        if k == 0:
            res.append(path)
            return 
        for i in range(start, len(nums)):
            # i > start ensures that we don't reuse the same number
            # nums[i] is not in path ensures that we don't use the same number twice
            if i > start and nums[i] == nums[i-1]:
