def parse_catalog(xml_text: str) -> list[dict]:
    root = ET.fromstring(xml_text)
    books = root.findall('book')
    result = []

    for book in books:
        book_id = book.get('id')
        title = book.find('title')
        author = book.find('author')

        if title is None:
            title = ""
        else:
            title = title.text

        if author is None:
            author = ""
        else:
            author = author.text

        result.append({"id": book_id, "title": title, "author": author})

    return result

