def seating_arrangements(guests: list[str], conflicts: list[tuple[str, str]]) -> list[list[str]]:
    conflicts_dict = {guest: set() for guest in guests}
    for a, b in conflicts:
        if a in conflicts_dict and b in conflicts_dict:
            conflicts_dict[a].add(b)
            conflicts_dict[b].add(a)

    arrangements = []
    def backtrack(start_index, current_arrangement):
        if start_index == len(guests):
            arrangements.append(current_arrangement[:])
            return

        for i in range(start_index, len(guests)):
            if all(guests[i] not in conflicts_dict[guests[j]] for j in range(start_index)):
                guests[start_index], guests[i] = guests[i], guests[start_index]
                current_arrangement.append(guests[start_index])
                backtrack(start_index + 1, current_arrangement)
                current_arrangement.pop()
                guests[start_index], guests[i] = guests[i], guests[start_index]

    backtrack(0, [])
    arrangements.sort()
    return arrangements
```

