def convert_base(number: str, from_base: int, to_base: int) -> str:
    if not 2 <= from_base <= 36 or not 2 <= to_base <= 36:
        raise ValueError("Bases must be between 2 and 36")

    if not number or number == "-" or any(not (ord('0') <= ord(c) <= ord('9') or ord('a') <= ord(c) <= ord('z') or ord('A') <= ord(c) <= ord('Z')) for c in number[1:] if c != '-'):
        raise ValueError("Invalid number")

    negative = number[0] == '-'
    number = number.lower()
    if negative:
        number = number[1:]

    base10 = int(number, from_base)
    if to_base == 10:
        return '-' + str(base10) if negative else str(base10)

    if base10 == 0:
        return '0'

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = ""
    while base10:
        base10, remainder = divmod(base10, to_base)
        result = digits[remainder] + result

    return '-' + result if negative else result
