def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs in descending order of profit
    jobs.sort(key=lambda x: (-x[2], x))

    # Initialize an empty list to store the scheduled jobs
    schedule = [None] * max(job[1] for job in jobs if job[1] > 0)

    # Schedule each job
    for job in jobs:
        if job[1] > 0:
            for i in range(job[1] - 1, -1, -1):
                if schedule[i] is None:
                    schedule[i] = job[0]
                    break

    # Return the names of the scheduled jobs
    return [job for job in schedule if job is not None]
