def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times:
        return []

    events = [(arrivals[i], service_times[i]) for i in range(len(arrivals))]
    events.sort()

    free_times = [0] * tellers
    wait_times = [0] * len(events)

    for i in range(len(events)):
        earliest_free_time = min(free_times)
        if events[i][0] > earliest_free_time:
            wait_times[i] = events[i][0] - earliest_free_time
            free_times[free_times.index(earliest_free_time)] = events[i][0] + events[i][1]
        else:
            wait_times[i] = 0
            free_times[free_times.index(earliest_free_time)] += events[i][1]

    return wait_times

