            # Move left to top
            new_matrix[first][i] = new_matrix[last - i][first]

            # Move bottom to left
            new_matrix[last - i][first] = new_matrix[last][last - i]

            # Move right to bottom
            new_matrix[last][last - i] = new_matrix[i][last]

            # Move saved top to right
            new_matrix[i][last] = top

