import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, w in edges:
        if u not in graph: graph[u] = {}
        if v not in graph: graph[v] = {}
        graph[u][v] = w
        graph[v][u] = w

    shortest_distances = {node: float('inf') for node in graph}
    shortest_distances[start] = 0
    previous_nodes = {node: None for node in graph}

    queue = [(0, start)]
    while queue:
        dist, node = heapq.heappop(queue)
        if dist != shortest_distances[node]:
            continue
        for neighbor, neighbor_dist in graph[node].items():
            old_dist = shortest_distances[neighbor]
            new_dist = dist + neighbor_dist
            if new_dist < old_dist:
                shortest_distances[neighbor] = new_dist
                previous_nodes[neighbor] = node
                heapq.heappush(queue, (new_dist, neighbor))

    if shortest_distances[goal] == float('inf'):
        return None

    path = []
    while goal is not None:
        path.append(goal)
        goal = previous_nodes[goal]
    path.reverse()

    return (shortest_distances[path[-1]], path)
```

