class FormulaEvaluator(ast.NodeVisitor):
    def __init__(self, x):
        self.x = x

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            if right == 0:
                raise ZeroDivisionError("division by zero")
            return left / right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        else:
            raise ValueError("unsupported operator")

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -operand
        else:
            raise ValueError("unsupported unary operator")

    def visit_Num(self, node):
        return node.n

    def visit_Name(self, node):
        if node.id == 'x':
            return self.x
        else:
            raise ValueError("unsupported variable")

    def visit_Call(self, node):
        func_name = node.func.id
        arg = self.visit(node.args[0])
        if func_name == 'sqrt':
            return math.sqrt(arg)
        elif func_name == 'abs':
            return math.fabs(arg)
        elif func_name == 'sin':
            return math.sin(arg)
        elif func_name == 'cos':
            return math.cos(arg)
        else:
            raise ValueError("unsupported function")

def evaluate_formula(formula: str, x: float) -> float:
    tree = ast.parse(formula, mode='eval').body
    evaluator = FormulaEvaluator(x)
    return evaluator.visit(tree)
