        new = node
        prev.next = new
        new.prev = prev
        new.next = tail
        tail.prev = new

    def move_to_end(node):
        remove_node(node)
        add_node(node)

    def get(key):
        if key in cache:
            node = cache[key]
            move_to_end(node)
            return node.value
        else:
            return None

    def put(key, value):
