    for mo in re.finditer(tok_regex, source):
        kind = mo.lastgroup
        if kind == "SKIP":
            continue
        elif kind == "NUMBER" or kind == "NAME":
            text = mo.group(kind)
            tokens.append((kind, text))
        elif kind == "OP":
            text = mo.group(kind)
            if text in ["==", "!=", "<=", ">="]:
                tokens.append(("OP", text[0]))
                tokens.append(("OP", text[1:]))
            else:
                tokens.append((kind, text))
    return tokens

