def league_table(results: list[tuple[str, str, int, int]]) -> list[tuple[str, int, int, int]]:
    teams = {}
    for match in results:
        home, away, home_goals, away_goals = match
        if home not in teams:
            teams[home] = [0, 0, 0, 0]  # points, goal_difference, goals_scored, matches_played
        if away not in teams:
            teams[away] = [0, 0, 0, 0]
        teams[home][3] += 1  # increment matches_played
        teams[away][3] += 1
        if home_goals > away_goals:
            teams[home][0] += 3  # home team wins, add 3 points
            teams[home][1] += home_goals - away_goals  # update goal_difference
            teams[home][2] += home_goals  # update goals_scored
            teams[away][1] -= away_goals  # update goal_difference
            teams[away][2] += away_goals  # update goals_scored
        elif home_goals < away_goals:
            teams[away][0] += 3  # away team wins, add 3 points
