def teller_waits(arrivals: list[int], service_times: list[int], tellers: int) -> list[int]:
    if not arrivals or not service_times:
        return []

    events = [(arrivals[i], service_times[i], i) for i in range(len(arrivals))]
    events.sort()

    wait_times = [0] * len(arrivals)
    free_times = [0] * tellers

    for event in events:
        earliest_free_time = min(free_times)
        if event[0] < earliest_free_time:
            wait_times[event[2]] = earliest_free_time - event[0]
            free_times[free_times.index(earliest_free_time)] = event[0] + event[1]
        else:
            wait_times[event[2]] = event[0] - earliest_free_time
            free_times[free_times.index(earliest_free_time)] = event[0] + event[1]

    return wait_times

