import re

def is_allowed_webhook(url: str) -> bool:
    # Check if url starts with https://
    if not url.lower().startswith('https://'):
        return False

    # Check if url contains any backslash, space, or control character
    if any(c in url for c in ['\\', ' ', '\t', '\n', '\r', '\f', '\v']):
        return False

    # Check if url host ends with a . and is a valid DNS name
    try:
        host = url.split('/')[2].split(':')[0]
        if not re.match(r'^([a-zA-Z0-9]+\.)+[a-zA-Z]{2,}$', host):
            return False
    except IndexError:
        return False

    # Check if url host is localhost or ends with .localhost
    if host.lower() in ['localhost', 'localhost.']:
        return False

    # Check if url port is absent or 443
    try:
        port = url.split(':')[2].split('/')[0]
        if port != '443':
            return False
    except IndexError:
        pass

    return True
