import operator
import math

OPERATORS = {'+': (1, operator.add), '-': (1, operator.sub), '*': (2, operator.mul), '/': (2, operator.floordiv), '^': (3, operator.pow)}

def evaluate_expression(expr: str) -> int:
    def parse_token(token: str) -> int:
        try:
            return int(token)
        except ValueError:
            return token

    def parse_expr(tokens: list) -> int:
        stack = []
        for token in tokens:
            if token in OPERATORS:
                while (stack and stack[-1] != "(" and OPERATORS[token][0] <= OPERATORS[stack[-1]][0]):
                    arg2 = stack.pop()
                    operator_fn = stack.pop()
                    arg1 = stack.pop()
                    stack.append(OPERATORS[operator_fn][1](arg1, arg2))
                stack.append(token)
            elif token == ")":
                arg2 = stack.pop()
                operator_fn = stack.pop()
                arg1 = stack.pop()
                while operator_fn != "(":
                    stack.append(OPERATORS[operator_fn][1](arg1, arg2))
                    arg2 = stack.pop()
                    operator_fn = stack.pop()
                    if stack:
                        arg1 = stack[-1]
                    else:
                        break
            else:
                stack.append(parse_token(token))
        while len(stack) != 1:
            arg2 = stack.pop()
            operator_fn = stack.pop()
            arg1 = stack.pop()
            stack.append(OPERATORS[operator_fn][1](arg1, arg2))
        return stack[0]

    return parse_expr(expr.split())
