def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = {}
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
            while waiting.get(item, 0) > 0 and stock.get(item, 0) >= waiting[item]:
                stock[item] -= waiting[item]
                waiting[item] = 0
        elif kind == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]
            else:
                if item in waiting:
                    waiting[item] += quantity
                else:
                    waiting[item] = quantity
    waiting = sorted((item, quantity) for item, quantity in waiting.items())
    return stock, waiting
