def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pointer = 0
    max_instructions = 1000

    while pointer < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pointer].split()
        op = instruction[0]

        if op == 'PUSH':
            stack.append(int(instruction[1]))
        elif op == 'POP':
            if not stack:
                return None
            stack.pop()
        elif op == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            pointer = int(instruction[1])
            continue
        elif op == 'JZ':
            if not stack:
                return None
            if stack.pop() == 0:
                pointer = int(instruction[1])
                continue
        pointer += 1

    return stack if max_instructions > 0 else None
