def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []
    pending = {}

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

            # Fulfill pending orders
            while pending.get(item, 0) > 0 and stock[item] >= quantity:
                pending[item] -= quantity
                if pending[item] == 0:
