def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    pointer = 0
    max_instructions = 1000

    while pointer < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[pointer].split()
        opcode = instruction[0]

        if opcode == 'PUSH':
            stack.append(int(instruction[1]))
        elif opcode == 'POP':
            if not stack:
                return None
            stack.pop()
        elif opcode == 'DUP':
            if len(stack) < 1:
                return None
            stack.append(stack[-1])
        elif opcode == 'SWAP':
            if len(stack) < 2:
                return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif opcode == 'ADD':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif opcode == 'SUB':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif opcode == 'MUL':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif opcode == 'JMP':
            target = int(instruction[1])
            if target < 0 or target >= len(program):
                return None
            pointer = target
            continue
        elif opcode == 'JZ':
            target = int(instruction[1])
            if target < 0 or target >= len(program):
                return None
            if not stack or stack[-1] != 0:
                pointer += 1
                continue
            pointer = target
            continue

        pointer += 1

    return stack if max_instructions > 0 else None
