def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0  # instruction pointer
    max_instructions = 1000
    while ip < len(program) and max_instructions > 0:
        max_instructions -= 1
        instruction = program[ip].split()
        op = instruction[0]
        if op == 'PUSH':
            stack.append(int(instruction[1]))
        elif op == 'POP':
            if not stack:
                raise ValueError('Not enough values on the stack')
            stack.pop()
        elif op == 'DUP':
            if len(stack) < 1:
                raise ValueError('Not enough values on the stack')
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Not enough values on the stack')
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'ADD':
            if len(stack) < 2:
                raise ValueError('Not enough values on the stack')
            stack.append(stack.pop() + stack.pop())
        elif op == 'SUB':
            if len(stack) < 2:
                raise ValueError('Not enough values on the stack')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                raise ValueError('Not enough values on the stack')
            stack.append(stack.pop() * stack.pop())
        elif op == 'JMP':
            if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                raise ValueError('Invalid JMP instruction')
            ip = int(instruction[1])
            continue
        elif op == 'JZ':
            if len(stack) < 1:
                raise ValueError('Not enough values on the stack')
            if stack[-1] == 0:
                if len(instruction) != 2 or not instruction[1].isdigit() or int(instruction[1]) >= len(program):
                    raise ValueError('Invalid JZ instruction')
                ip = int(instruction[1])
                stack.pop()
                continue
            stack.pop()
        elif op == 'HALT':
            break
        else:
            raise ValueError('Invalid instruction')
        ip += 1
    if max_instructions == 0:
