def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    pc = 0  # Program counter
    max_instructions = 1000

    while pc < len(program) and pc < max_instructions:
        instruction = program[pc]
        pc += 1

        if instruction == 'HALT':
            break

        elif instruction == 'POP':
            if not stack:
                raise ValueError('Stack underflow')
            stack.pop()

        elif instruction == 'DUP':
            if len(stack) < 1:
                raise ValueError('Stack underflow')
            stack.append(stack[-1])

        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise ValueError('Stack underflow')
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif instruction == 'ADD':
            if len(stack) < 2:
                raise ValueError('Stack underflow')
            stack.append(stack.pop() + stack.pop())

        elif instruction == 'SUB':
            if len(stack) < 2:
                raise ValueError('Stack underflow')
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)

        elif instruction == 'MUL':
            if len(stack) < 2:
                raise ValueError('Stack underflow')
            stack.append(stack.pop() * stack.pop())

        elif instruction.startswith('PUSH'):
            stack.append(int(instruction.split()[1]))

        elif instruction.startswith('JMP'):
            pc = int(instruction.split()[1])
            pc -= 1  # Because we'll increment pc at the end of the loop

        elif instruction.startswith('JZ'):
            if not stack:
                raise ValueError('Stack underflow')
            if stack[-1] == 0:
                pc = int(instruction.split()[1])
                pc -= 1  # Because we'll increment pc at the end of the loop
            stack.pop()

        else:
            raise ValueError('Invalid instruction')

    if pc == max_instructions:
        raise RuntimeError('Maximum number of instructions executed')

    return stack
