def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    frozen = {}
    failed = []
    final_balances = balances.copy()

    for i, op in enumerate(ops):
        op_type, account, *args = op

        if account not in final_balances:
            failed.append(i)
            continue

        if op_type == 'freeze' or op_type == 'unfreeze':
            if account in frozen:
                if op_type == 'freeze':
                    continue
                else:
                    del frozen[account]
                    continue
            else:
                if op_type == 'freeze':
                    frozen[account] = True
                else:
                    failed.append(i)
                continue

        amount = args[0]

        if amount <= 0 or (account in frozen) or (op_type in ['deposit', 'withdraw'] and final_balances[account] - amount < 0):
            failed.append(i)
            continue

        if op_type == 'deposit':
            final_balances[account] += amount
        elif op_type == 'withdraw':
            final_balances[account] -= amount
        elif op_type == 'transfer':
            target = args[1]
            if account == target or target not in final_balances or final_balances[account] - amount - 2 < 0 or (target in frozen):
                failed.append(i)
                continue
            final_balances[account] -= amount + 2
            final_balances[target] += amount

    return final_balances, failed
